// decision: docs/decision-records/0028-an-event-copy-is-an-instance-of-its-episode.md
import type { OutlineInput, TracedSlide } from './episode-outline.pure.ts';
import type { RegistryFile } from './episode-registry.pure.ts';

const INSTANCE_SLIDES_PATH = 'src/episodes/lib/episode-instance-slides.generated.ts';
const LOCALES = ['en', 'de'] as const;
const HEADER = [
  '// The Slide messages of every Base Episode, generated by `npm run registry` from the Episode outline: never edit by',
  '// hand. `instanceOf(base, { slides: { <slug>: … } })` types each Slide override from the map for its base.',
].join('\n');

function identifierOf(...parts: readonly string[]): string {
  const camel = parts.map((part) => part.replace(/-([a-z0-9])/g, (_, next: string) => next.toUpperCase())).join('__');
  return /^[0-9]/.test(camel) ? `_${camel}` : camel;
}

const aliasOf = (file: string): string => file.replace(/^src\//, '@/');

function baseSlides(base: OutlineInput): TracedSlide[] {
  return [...(base.title === undefined ? [] : [base.title]), ...base.sections.flat()];
}

function baseOf(instance: OutlineInput, byId: ReadonlyMap<string, OutlineInput>): OutlineInput {
  const base = instance.base === undefined ? undefined : byId.get(instance.base);
  if (base === undefined)
    throw new Error(
      `The Episode instance ${instance.id} names the Base Episode "${instance.base}", which has no outline`,
    );
  return base;
}

function basesOf(episodes: readonly OutlineInput[]): OutlineInput[] {
  const byId = new Map(episodes.map((episode) => [episode.id, episode]));
  const bases = new Map(
    episodes.filter((episode) => episode.base !== undefined).map((episode) => [episode.base, baseOf(episode, byId)]),
  );
  return [...bases.values()].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
}

function importsOf(base: OutlineInput): string[] {
  return baseSlides(base).flatMap((slide) =>
    LOCALES.map((locale) => {
      const file = slide.text[locale]?.[0];
      if (typeof file !== 'string') throw new Error(`Slide "${slide.slug}" of ${base.id} has no ${locale} text file`);
      return `import type ${identifierOf(base.id, slide.slug, locale)} from '${aliasOf(file)}';`;
    }),
  );
}

function entryOf(base: OutlineInput): string {
  const slides = baseSlides(base).map((slide) => {
    const [en, de] = LOCALES.map((locale) => `typeof ${identifierOf(base.id, slide.slug, locale)}`);
    return `      readonly ${JSON.stringify(slide.slug)}: { readonly en: ${en}; readonly de: ${de} };`;
  });
  return [`    readonly ${JSON.stringify(base.id)}: {`, ...slides, '    };'].join('\n');
}

export function instanceSlidesFile(episodes: readonly OutlineInput[]): RegistryFile {
  const bases = basesOf(episodes);
  const text = `${bases.flatMap(importsOf).join('\n')}

${HEADER}
declare module './episode-instance' {
  interface BaseSlideMessages {
${bases.map(entryOf).join('\n')}
  }
}

export {};
`;
  return { path: INSTANCE_SLIDES_PATH, text };
}
